<?php
declare(strict_types=1);
require dirname(__DIR__).'/private/bootstrap.php';require_once dirname(__DIR__).'/private/curriculum-review.php';
try{session_begin();$u=account_user();curriculum_review_guard($u);$method=$_SERVER['REQUEST_METHOD'];if($method==='GET'){limited('curriculum-review',180,60,$u['id']);$course=$_GET['course']??'';$module=$_GET['module']??'0';demand(is_string($course)&&is_string($module),'Choose a course page.');reply(['csrf'=>$_SESSION['csrf']]+curriculum_review_payload($u,$course,$module));}if($method==='POST'){$b=student_request_body(50000);if(($b['action']??'')==='setup'){curriculum_review_install();school_presence_install();reply(['notice'=>'Private review and activity indicators are ready.']);}limited('curriculum-suggestions',120,3600,$u['id']);reply(['csrf'=>$_SESSION['csrf'],'saved'=>curriculum_save_note($u,$b),'notice'=>'Suggestion saved privately. Published lessons have not been changed.']);}reply(['error'=>'Method not allowed.'],405);}catch(InvalidArgumentException|JsonException $e){reply(['error'=>$e instanceof InvalidArgumentException?$e->getMessage():'Refresh this review.'],400);}catch(Throwable $e){error_log('Curriculum review unavailable: '.get_class($e));reply(['error'=>'The review could not be loaded. Please retry.'],503);}
